@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class EventType {
  + name : string
}

class Location {
  + name : string
  + address : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Task {
  + description : string
  + status : string
}

class EventTask {
  + status : string
}

class Item {
  + description : string
}

Organizer "1..*" -- "*" Event : organizes
Organizer "0..1" -- "*" Event : attends
Attendee "0..*" -- "*" Event : attends
Attendee "0..1" -- "*" Event : attends
Event "*" -- "1" EventType
Event "*" -- "0..1" Location
Event "1" *-- "0..*" EventTask
EventTask "0..*" -- "0..1" Task : is a template for
EventTask "0..1" -- "0..1" Attendee : assigned to
Attendee "0..*" -- "0..*" Item : brings

@enduml

